Create Channel.code:
// Create a channel that proxies /fhir/* to a shared health record.
createChannel({
  name: 'Shared Health Record (FHIR)',
  type: 'http',
  status: 'enabled',
  // Only clients with one of these roles may use the channel.
  authType: 'private',
  allow: ['fhir'],
  // Requests whose path matches this regex use this channel.
  urlPattern: '^/fhir/.*$',
  methods: ['GET', 'POST', 'PUT'],
  routes: [
    {
      name: 'HAPI FHIR',
      host: 'hapi-fhir',
      port: 8080,
      primary: true,
      secured: false,
    },
  ],
  // Store bodies on transactions for auditing.
  requestBody: true,
  responseBody: true,
});

Register Client.code:
// Register a client system that will call OpenHIM channels.
createClient({
  // Unique id the client authenticates with.
  clientID: $.data.clientId,
  name: 'District EMR',
  // Roles decide which channels the client may use.
  roles: ['fhir'],
  // Basic-auth password, pre-hashed (never store plain text).
  passwordAlgorithm: 'sha512',
  passwordSalt: $.data.passwordSalt,
  passwordHash: $.data.passwordHash,
});

Rerun Failed Transactions.code:
// Queue transactions to be rerun through their channels.
createTask({
  // Ids of the transactions to rerun (e.g. from getTransactions).
  tids: $.data.failedTransactionIds,
  // How many to rerun at once.
  batchSize: 5,
  // Start the task immediately.
  paused: false,
});

Get Failed Transactions.code:
// Get the most recent failed transactions.
getTransactions({
  filterLimit: 50,
  filterPage: 0,
  // Filters are a JSON string.
  filters: JSON.stringify({ status: 'Failed' }),
});

List Channels.code:
// List every channel.
getChannels();

// Or fetch one channel by id:
// getChannels($.data.channelId);

List Clients.code:
// List every registered client.
getClients();

// Or fetch one client by id:
// getClients($.data.clientId);

Get Rerun Tasks.code:
// List rerun tasks.
getTasks({
  filterLimit: 10,
  filterPage: 0,
  filters: '{}',
});
